      "src/App.css": {
        "type": "file",
        "isBinary": false,
        "content": "#root {\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 2rem;\n  text-align: center;\n}\n\n.logo {\n  height: 6em;\n  padding: 1.5em;\n  will-change: filter;\n  transition: filter 300ms;\n}\n.logo:hover {\n  filter: drop-shadow(0 0 2em #646cffaa);\n}\n.logo.react:hover {\n  filter: drop-shadow(0 0 2em #61dafbaa);\n}\n\n@keyframes logo-spin {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n@media (prefers-reduced-motion: no-preference) {\n  a:nth-of-type(2) .logo {\n    animation: logo-spin infinite 20s linear;\n  }\n}\n\n.card {\n  padding: 2em;\n}\n\n.read-the-docs {\n  color: #888;\n}\n"
      },
      "src/App.tsx": {
        "type": "file",
        "isBinary": false,
        "content": "import { Toaster } from '@/components/ui/toaster'\nimport { Toaster as Sonner } from '@/components/ui/sonner'\nimport { TooltipProvider } from '@/components/ui/tooltip'\nimport { QueryClient, QueryClientProvider } from '@tanstack/react-query'\nimport { BrowserRouter, Routes, Route, Outlet, Link } from 'react-router-dom'\nimport { AuthProvider, RequireAdmin, RequireAuth } from '@/lib/auth'\nimport {\n  NavigationMenu,\n  NavigationMenuList,\n  NavigationMenuItem,\n  NavigationMenuLink,\n} from '@/components/ui/navigation-menu'\nimport Index from './pages/Index'\nimport Login from './pages/Login'\nimport Signup from './pages/Signup'\nimport Reset from './pages/Reset'\nimport Dashboard from './pages/Dashboard'\nimport Admin from './pages/Admin'\nimport Shop from './pages/Shop'\nimport About from './pages/About'\nimport Contact from './pages/Contact'\n\nconst queryClient = new QueryClient()\n\nconst MainNav = () => (\n  <NavigationMenu className='mb-2 w-full border-b bg-background'>\n    <NavigationMenuList>\n      <NavigationMenuItem>\n        <NavigationMenuLink asChild>\n          <Link to='/' className='px-4 py-2 font-medium hover:underline'>\n            Home\n          </Link>\n        </NavigationMenuLink>\n      </NavigationMenuItem>\n      <NavigationMenuItem>\n        <NavigationMenuLink asChild>\n          <Link to='/about' className='px-4 py-2 font-medium hover:underline'>\n            About\n          </Link>\n        </NavigationMenuLink>\n      </NavigationMenuItem>\n      <NavigationMenuItem>\n        <NavigationMenuLink asChild>\n          <Link to='/contact' className='px-4 py-2 font-medium hover:underline'>\n            Contact\n          </Link>\n        </NavigationMenuLink>\n      </NavigationMenuItem>\n      <NavigationMenuItem>\n        <NavigationMenuLink asChild>\n          <Link to='/login' className='px-4 py-2 font-medium hover:underline'>\n            Login\n          </Link>\n        </NavigationMenuLink>\n      </NavigationMenuItem>\n      <NavigationMenuItem>\n        <NavigationMenuLink asChild>\n          <Link to='/signup' className='px-4 py-2 font-medium hover:underline'>\n            Sign up\n          </Link>\n        </NavigationMenuLink>\n      </NavigationMenuItem>\n    </NavigationMenuList>\n  </NavigationMenu>\n)\n\nconst RootWithNav = () => (\n  <>\n    <MainNav />\n    <Outlet />\n  </>\n)\n\nconst App = () => (\n  <QueryClientProvider client={queryClient}>\n    <TooltipProvider>\n      <Toaster />\n      <Sonner />\n      <BrowserRouter>\n        <AuthProvider>\n          <Routes>\n            <Route path='/' element={<RootWithNav />}>\n              <Route index element={<Index />} />\n              <Route path='about' element={<About />} />\n              <Route path='contact' element={<Contact />} />\n              <Route path='login' element={<Login />} />\n              <Route path='signup' element={<Signup />} />\n              <Route path='reset' element={<Reset />} />\n              {/* Kept for agent rewrites that need a shop route; not in default nav */}\n              <Route path='shop' element={<Shop />} />\n              <Route\n                path='dashboard'\n                element={\n                  <RequireAuth>\n                    <Dashboard />\n                  </RequireAuth>\n                }\n              />\n              <Route\n                path='admin'\n                element={\n                  <RequireAdmin>\n                    <Admin />\n                  </RequireAdmin>\n                }\n              />\n            </Route>\n          </Routes>\n        </AuthProvider>\n      </BrowserRouter>\n    </TooltipProvider>\n  </QueryClientProvider>\n)\n\nexport default App\n"
      },
